      assigneeId: input.assigneeId,
      parentId: input.parentId,
      estimate: input.estimate,
      dueAt: input.dueAt,
      startedAt: null,
      completedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

